/*
 * canon-check: the independent certificate checker (docs/specification.md section 20, 3.2;
 * slice S7, docs/slices/S7.md 3.4).  This program shares no code, header, type or constant
 * with the canon library: it depends on the C standard library only (checker/README.md).
 *
 * It decides whether a CERT-0 certificate (the format is restated in checker/README.md) proves
 * that the stated bytes are the profile P1 canonical image (spec 7.1, 7.2) of the stated object
 * under the group generated by the stated generators.  Every rule it applies cites the spec
 * section it implements.  Acceptance means: under the trusted assumptions (compiler, runtime)
 * the engine's claim holds; it does not establish the engine's memory safety (spec 20).
 *
 * Convention (spec 3): a permutation is an array p with p[v] = v^p; products act left to right,
 * (pq)[v] = q[p[v]]; a list acts on the right, L^p = (p[L[0]], p[L[1]], ...).
 */
#ifndef CANON_CHECKER_CC_H
#define CANON_CHECKER_CC_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define CC_NONE UINT32_MAX

/* The largest single allocation this checker makes (bytes).  A size beyond it is CC_CAPACITY, a
 * limit of the checker and never a verdict on the certificate; every array sized from the stream
 * is also bounded by the bytes that must follow it (CC_TRUNCATED), so this cap is only reached
 * by the p x n provenance evaluation of a chain. */
#define CC_MAX_ALLOC ((size_t)1 << 30)

/* ---- reasons: every rejection names its rule ---- */

typedef enum cc_reason {
    CC_ACCEPT = 0,
    CC_TRUNCATED,            /* the stream ended inside a field */
    CC_TRAILING_BYTES,       /* bytes after the final claim */
    CC_CAPACITY,             /* a size does not fit this checker's limits */
    CC_HEADER,               /* magic or a frozen identifier is not the expected one */
    CC_DEGREE_MISMATCH,      /* the object stream's n differs from the header's */
    CC_OBJECT_MALFORMED,     /* the CDAG-2 stream of x is not well formed (spec 4.1) */
    CC_OBJECT_UNSUPPORTED,   /* a root other than a set of atoms or a graph (v0) */
    CC_GENERATOR_NOT_BIJECTION,
    CC_ROOT_CHAIN_INPUTS,    /* the root chain's inputs are not the generator list */
    CC_CHAIN_STRUCTURE,      /* chain fields out of range */
    CC_CHAIN_NOT_BIJECTION,
    CC_CHAIN_PROVENANCE,     /* a generator is not what its record derives */
    CC_CHAIN_PREFIX_NOT_FIXED,
    CC_CHAIN_NOT_NESTED,
    CC_CHAIN_ORBIT_TREE,     /* root, duplicate, edge or reachability of a stored orbit */
    CC_CHAIN_ORBIT_NOT_CLOSED,
    CC_CHAIN_TRANSVERSAL,
    CC_CHAIN_SCHREIER_RESIDUE,
    CC_CHAIN_INPUT_NOT_MEMBER,
    CC_AUTOMORPHISM_NOT_MEMBER,
    CC_AUTOMORPHISM_MOVES_X,
    CC_NODE_DEPTH,
    CC_NODE_ATOM,
    CC_SWEEP_COUNT,
    CC_STAGE_O_SIZES,
    CC_F_MISMATCH,
    CC_U_NOT_BIJECTION,
    CC_U_NOT_MEMBER,
    CC_M_MISMATCH,
    CC_REBASED_NOT_SAME_GROUP,
    CC_REBASED_BASE_PREFIX,
    CC_M_NOT_MINIMAL,
    CC_STAGE_G_SIZES,
    CC_LEAF_NOT_DISCRETE,
    CC_LEAF_T_MISMATCH,
    CC_BRANCH_AT_DISCRETE,
    CC_TARGET_CELL,
    CC_CHILD_NOT_IN_CELL,
    CC_CHILD_REPEATED,
    CC_CHILD_MISSING,
    CC_PRUNED_REP_NOT_EXPLORED,
    CC_PRUNED_AUTOMORPHISM_INDEX,
    CC_PRUNED_AUTOMORPHISM_MOVES_PREFIX,
    CC_PRUNED_AUTOMORPHISM_IMAGE,
    CC_PRUNED_UNDER_UNPRUNED_POLICY,
    CC_NODE_COUNT,
    CC_FINAL_TRACE,
    CC_FINAL_BYTES,
    CC_FINAL_WITNESS,
    CC_OUT_OF_MEMORY
} cc_reason;

const char *cc_reason_name(cc_reason r);

/* ---- byte reader (spec 4.1 big-endian fields) ---- */

typedef struct cc_reader {
    const uint8_t *data;
    size_t len, at;
} cc_reader;

bool cc_get_u8(cc_reader *r, uint8_t *out);
bool cc_get_u16(cc_reader *r, uint16_t *out);
bool cc_get_u32(cc_reader *r, uint32_t *out);
bool cc_get_u64(cc_reader *r, uint64_t *out);
/* B(s): *out points into the stream. */
bool cc_get_b(cc_reader *r, const uint8_t **out, uint32_t *len);
/* k x U32 into a new array (NULL with CC_OUT_OF_MEMORY / CC_CAPACITY in *why). */
uint32_t *cc_get_u32s(cc_reader *r, uint32_t k, cc_reason *why);

/* ---- checked allocation ---- */

/* malloc(count * size), or NULL with *why = CC_CAPACITY or CC_OUT_OF_MEMORY.  count 0 gives a
 * non-NULL block. */
void *cc_alloc(size_t count, size_t size, cc_reason *why);

/* ---- permutations (spec 3) ---- */

/* out[v] = q[p[v]]: pq, p first. */
void cc_compose(const uint32_t *p, const uint32_t *q, uint32_t *out, uint32_t n);
/* out[p[v]] = v. */
void cc_inverse(const uint32_t *p, uint32_t *out, uint32_t n);
bool cc_is_identity(const uint32_t *p, uint32_t n);
/* bitmap: (n + 63) / 64 words of scratch. */
bool cc_is_bijection(const uint32_t *p, uint32_t n, uint64_t *bitmap);
/* -1, 0, +1: numerical lexicographic order of image arrays (spec 7.2). */
int cc_perm_compare(const uint32_t *a, const uint32_t *b, uint32_t n);
/* spec 4.3: unsigned byte order, proper prefix smaller. */
int cc_bytes_compare(const uint8_t *a, size_t a_len, const uint8_t *b, size_t b_len);

/* ---- stabiliser chain (spec 9.1, 9.2): deserialised from the CHAIN layout ---- */

typedef struct cc_level {
    uint32_t base, r;       /* base point, orbit length */
    uint32_t *orbit;        /* r */
    uint32_t *parent_point; /* r (CC_NONE at position 0) */
    uint32_t *parent_gen;   /* r: index into gen_ids (CC_NONE at position 0) */
    uint32_t s;             /* generator count */
    uint32_t *gen_ids;      /* s: generator ids */
    uint32_t *pos;          /* n: orbit position of a point, or CC_NONE */
} cc_level;

typedef struct cc_chain {
    uint32_t n, depth;
    cc_level *levels;   /* depth */
    uint32_t g;         /* generators */
    uint32_t *gen_node; /* g: provenance node of each generator */
    uint32_t *gens;     /* g x n */
    uint32_t *invs;     /* g x n, computed here */
    uint32_t p;         /* provenance nodes */
    uint32_t *prov;     /* 3 p: kind, a, b */
    uint32_t i;         /* inputs */
    uint32_t *inputs;   /* i x n */
    bool verified;
} cc_chain;

void cc_chain_init(cc_chain *c);
void cc_chain_free(cc_chain *c);
/* Read a CHAIN of degree n (CC_CHAIN_STRUCTURE if its own n differs). */
cc_reason cc_chain_read(cc_reader *r, uint32_t n, cc_chain *c);
/* spec 9.1 third paragraph: the verifier's conditions, plus nesting (checker/README.md lists
 * them).  Sets c->verified on CC_ACCEPT. */
cc_reason cc_chain_verify(cc_chain *c);
/* spec 9.2 membership: true iff p is in the group (c verified).  scratch: n words. */
bool cc_chain_contains(const cc_chain *c, const uint32_t *p, uint32_t *scratch);
/* spec 7.1 G stage: orbit_id[v] = rank of the orbit of v under the group generated by the
 * strong generators of `level` (the pointwise stabiliser of the first `level` base points;
 * level == depth: the trivial group), orbits ranked by their least point.  scratch: n words. */
void cc_chain_orbit_ids(const cc_chain *c, uint32_t level, uint32_t *orbit_id, uint32_t *scratch);
/* The least point of the orbit of level i. */
uint32_t cc_level_min(const cc_level *L);

/* ---- objects (spec 2.1, 4.1, 4.2): a set of atoms or a coloured directed multigraph ---- */

typedef struct cc_arc {
    uint32_t source, target;
    uint32_t label;        /* rank in the label table (B order) */
    uint64_t multiplicity; /* > 0 */
} cc_arc;

typedef struct cc_bytes {
    const uint8_t *data; /* into the object stream */
    uint32_t len;
} cc_bytes;

typedef struct cc_object {
    bool graph;
    uint32_t n;
    /* subset */
    uint32_t k;
    uint32_t *atoms;      /* k, strictly increasing */
    uint8_t *member;      /* n */
    /* graph */
    bool owns_tables;     /* false for an image, which borrows its source's tables */
    uint32_t colour_count, label_count;
    cc_bytes *colours;    /* colour_count distinct strings, B order */
    cc_bytes *labels;     /* label_count distinct strings, B order */
    uint32_t *colour_of;  /* n: rank */
    uint32_t e;
    cc_arc *arcs;         /* e, sorted by (source, target, label), distinct */
} cc_object;

void cc_object_init(cc_object *x);
void cc_object_free(cc_object *x);
/* Decode a CDAG-2 stream of degree n into x (spec 4.1): a root that is a set of atoms (tags
 * 01, 04) or a graph record (tag 09); anything else CC_OBJECT_UNSUPPORTED. */
cc_reason cc_object_decode(const uint8_t *stream, size_t len, uint32_t n, cc_object *x);
/* x^p (spec 2.1 ATOM-TRANSPORT-1) into img (storage reused; img may not be x). */
cc_reason cc_object_act(const cc_object *x, const uint32_t *p, cc_object *img);
/* Extensional equality (spec 4.2). */
bool cc_object_equal(const cc_object *a, const cc_object *b);
/* The canonical CDAG-2 stream of x (spec 4.1, 4.2) into a growable buffer. */
typedef struct cc_buf {
    uint8_t *data;
    size_t len, cap;
} cc_buf;
void cc_buf_init(cc_buf *b);
void cc_buf_free(cc_buf *b);
bool cc_buf_put(cc_buf *b, const uint8_t *bytes, size_t len);
bool cc_buf_put_u8(cc_buf *b, uint8_t v);
bool cc_buf_put_u32(cc_buf *b, uint32_t v);
cc_reason cc_object_encode(const cc_object *x, cc_buf *out);
/* spec 7.1 initial key of atom a: membership 0/1 on a subset, the colour's rank on a graph. */
uint32_t cc_object_initial_key(const cc_object *x, uint32_t a);

/* ---- ordered partitions and P1 refinement (spec 7.1, 10) ---- */

typedef struct cc_partition {
    uint32_t n, cells;
    uint32_t *lab;     /* n: members cell by cell */
    uint32_t *start;   /* n + 1 */
    uint32_t *cell_of; /* n */
} cc_partition;

cc_reason cc_partition_init(cc_partition *p, uint32_t n);
void cc_partition_free(cc_partition *p);
void cc_partition_copy(cc_partition *dst, const cc_partition *src);
/* spec 7.1 split(P, sig): each cell replaced in place by its classes in increasing key order,
 * keys compared by cmp(ctx, a, b) on points.  tmp: n words.  Returns the number of cells. */
void cc_partition_split(cc_partition *p, int (*cmp)(void *ctx, uint32_t a, uint32_t b), void *ctx,
                        uint32_t *tmp);
void cc_partition_individualise(cc_partition *p, uint32_t cell, uint32_t a);
static inline uint32_t cc_cell_size(const cc_partition *p, uint32_t i)
{
    return p->start[i + 1] - p->start[i];
}

/* O-stage signatures (spec 7.1): dense exact counts, 2 L k per vertex. */
typedef struct cc_signatures {
    uint64_t *counts; /* n x width */
    size_t width;
} cc_signatures;
cc_reason cc_signatures_compute(const cc_object *x, const cc_partition *p, cc_signatures *s);
void cc_signatures_free(cc_signatures *s);

#endif /* CANON_CHECKER_CC_H */
